import { useState } from 'react';
import { Button, CommandPalette } from '@larose-ui/react';

export default function App() {
  const [open, setOpen] = useState(true);
  return (
    <>
      <Button onClick={() => setOpen(true)}>Open commands</Button>
      <CommandPalette
        open={open}
        onOpenChange={setOpen}
        items={[
          { id: 'new', label: 'New file', group: 'File', onSelect: () => setOpen(false) },
          { id: 'save', label: 'Save', group: 'File', onSelect: () => setOpen(false) },
        ]}
      />
    </>
  );
}
